{
  "cards": [
    {
      "advanced_exceptions": [],
      "context_id": "",
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Name: Aphelios. Official role tags: Marksman.",
              "source_id": "riot:role"
            },
            {
              "quote": "Each weapon has a unique Basic Attack and Ability.",
              "source_id": "riot:P"
            },
            {
              "quote": "Other abilities will create mirror chakrams that he gathers, and his basic attacks deal bonus physical damage based on how many mirror chakrams he holds.",
              "source_id": "wiki:crescendum"
            },
            {
              "quote": "Active: Aphelios fires a concentrated blast of moonlight that explodes upon hitting an enemy champion, dealing physical damage to enemy champions in the area.",
              "source_id": "wiki:moonlightvigil"
            }
          ],
          "id": "overview_fighting_role",
          "summary": "Aphelios is a weapon-dependent marksman whose fighting centers on basic attacks, with a predominantly physical damage kit."
        },
        {
          "citations": [
            {
              "quote": "Aphelios has 5 different activated abilities, based on his main-hand weapon:Calibrum (Rifle): Long range shot that marks its target for a long-range follow-up attack.Severum (Scythe Pistol): Run fast while attacking nearby enemies with both weapons.Gravitum (Cannon): Root all enemies slowed by this weapon.Infernum (Flamethrower): Blast enemies in a cone and attack them with your off-hand weapon.Crescendum (Chakram): Deploy a sentry that shoots your off-hand weapon.",
              "source_id": "riot:Q"
            },
            {
              "quote": "Aphelios swaps his main-hand gun with his off-hand gun, replacing his basic attack and activated ability.",
              "source_id": "riot:W"
            },
            {
              "quote": "Aphelios has no third ability.",
              "source_id": "riot:E"
            },
            {
              "quote": "Fire a concentrated blast of moonlight that explodes on enemy champions. Applies the unique effect of Aphelios' main-hand gun.",
              "source_id": "riot:R"
            }
          ],
          "id": "overview_mobility",
          "summary": "The supplied complete active kit provides movement speed through Severum, but no dash or blink; his positioning remains vulnerable to being closed on."
        }
      ],
      "kind": "overview",
      "purpose": "Recognize an attack-focused marksman; assess his equipped weapons before choosing spacing or committing to an engage.",
      "slot": "",
      "source_ids": [
        "riot:role",
        "riot:P",
        "riot:Q",
        "riot:W",
        "riot:E",
        "riot:R",
        "wiki:crescendum",
        "wiki:moonlightvigil"
      ],
      "subject_id": "riot:role",
      "title": "Aphelios: weapon-dependent marksman",
      "unsupported_claims": []
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "The individual actives do not share a cooldown.",
              "source_id": "wiki:weaponsofthefaithful"
            }
          ],
          "status": "supported",
          "summary": "Weapon actives have independent cooldowns; swapping can expose a different available active."
        }
      ],
      "context_id": "",
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Aphelios wields 5 Lunari Weapons made by his sister Alune. He has access to two at a time: one main-hand and one off-hand. Each weapon has a unique Basic Attack and Ability.",
              "source_id": "riot:P"
            },
            {
              "quote": "The active effect of Aphelios' ability varies based on his current main weapon.",
              "source_id": "wiki:weaponsofthefaithful"
            }
          ],
          "id": "system_equipment",
          "summary": "His 5 weapons provide distinct attacks and abilities; he equips two at a time, with the main-hand weapon determining his active."
        },
        {
          "citations": [
            {
              "quote": "Attacks and abilities consume a weapon's ammo. When out of ammo, Aphelios discards the weapon and Alune summons the next of the 5.",
              "source_id": "riot:P"
            },
            {
              "quote": "Weapon order begins fixed but may change over game time -- when a weapon is out of ammo it goes to the end of the order.",
              "source_id": "riot:E"
            }
          ],
          "id": "system_ammo_cycle",
          "summary": "Attacks and abilities spend weapon ammunition; depletion replaces that weapon with the next reserve weapon and sends the depleted weapon to the queue's end."
        },
        {
          "citations": [
            {
              "quote": "Aphelios begins the game with Calibrum as his main weapon and Severum in his off-hand, with Gravitum, Infernum, and Crescendum queued in reserve.",
              "source_id": "wiki:thehitmanandtheseer"
            },
            {
              "quote": "Aphelios has no third ability. This slot shows the next weapon Alune will give him.",
              "source_id": "riot:E"
            },
            {
              "quote": "Active: Aphelios receives a text prompt of the weapon Alune will create next.",
              "source_id": "wiki:weaponqueuesystem"
            }
          ],
          "id": "system_queue_indicator",
          "summary": "He starts with Calibrum main-hand and Severum off-hand, followed by Gravitum, Infernum and Crescendum in reserve. E displays the next weapon and can show a text prompt; it is a queue indicator rather than a combat spell."
        },
        {
          "citations": [
            {
              "quote": "He starts the game with Phase and automatically gains access to his primary abilities at level 2 and his ultimate ability, Moonlight Vigil, at level 6. Moonlight Vigil improves automatically at levels 11 and 16.",
              "source_id": "wiki:thehitmanandtheseer"
            },
            {
              "quote": "Aphelios cannot improve his abilities via skill points.",
              "source_id": "wiki:thehitmanandtheseer"
            },
            {
              "quote": "Aphelios may spend his skill points to gain bonus attack damage, bonus attack speed or lethality instead.",
              "source_id": "wiki:thehitmanandtheseer"
            }
          ],
          "id": "system_unlocks",
          "summary": "Phase is available at the start; weapon actives unlock at level 2 and Moonlight Vigil at level 6, improving at levels 11 and 16. Skill points buy attack damage, attack speed or lethality instead of ability ranks."
        }
      ],
      "kind": "system",
      "purpose": "Track the equipped pair and ammunition cycle; anticipate changing threats and recognize the unusual early ability unlocks.",
      "slot": "P",
      "source_ids": [
        "riot:P",
        "riot:E",
        "wiki:thehitmanandtheseer",
        "wiki:weaponsofthefaithful",
        "wiki:weaponqueuesystem"
      ],
      "subject_id": "wiki:thehitmanandtheseer",
      "title": "Weapon arsenal, ammunition and unlocks",
      "unsupported_claims": []
    },
