  "conflicts": [
    {
      "resolution": "Treat E as a noncombat queue indicator with an informational text action. The wiki's 'Active' label does not establish a combat spell.",
      "source_ids": [
        "riot:E",
        "wiki:weaponqueuesystem"
      ],
      "topic": "E described as no ability versus an informational active"
    },
    {
      "resolution": "Teach qualitative ultimate effects. Exclude stale numerical values and the explicitly uncertain critical-damage anomaly.",
      "source_ids": [
        "wiki:moonlightvigil"
      ,"riot:R"],
      "topic": "Ultimate numerical notes include outdated values and an unverified bug"
    },
    {
      "resolution": "Use the explicit Calibrum attribution in the Calibrum section. Treat the Crescendum projectile note embedded in Moonshot as cross-topic detail, not a Moonshot mechanic.",
      "source_ids": [
        "wiki:moonshot",
        "wiki:calibrum",
        "wiki:crescendum"
      ],
      "topic": "Cross-topic notes embedded in ability sections"
    }
  ],
  "factual_risks": [
    "This is unapproved editorial material derived only from the supplied packet; no current-client verification was performed.",
    "The pinned Data Dragon release does not establish a current game patch label.",
